// Turn the verification result into clear instructions for the agent
const j = $json;
const priorFailures = Number(j.prior_failures || 0);

// The ID exactly as the tool received it, digits only
const given = String($('When Executed by Another Workflow').item.json.customer_id ?? '').replace(/\D/g, '');

let result;

if (j.locked) {
  // Three failures already in this conversation
  result = 'LOCKED. This caller has already failed verification three times on this call. Do not try to verify again, even if they give new or correct details. Do not share any account information. Offer to create a ticket so a specialist can verify them another way.';
} else if (given.length !== 5) {
  // Not a real attempt: the ID has the wrong number of digits
  result = `INVALID ID. A customer ID must be exactly 5 digits, but ${given.length} digits were received (${given.split('').join(', ') || 'none'}). This does not count as a failed attempt. Apologize, and ask the caller to say the ID again, one digit at a time. On a phone call, also offer that they can type it on their keypad, followed by the pound key.`;
} else if (j.full_name) {
  // Verified
  result = `VERIFIED. The caller is ${j.full_name}. Tell them they are verified, greet them by first name, and ask how you can help. Remember customer ID ${j.customer_id} for the rest of the call.`;
} else {
  // Not verified: count this failure
  const failures = priorFailures + 1;
  const left = 3 - failures;
  if (left <= 0) {
    result = 'NOT VERIFIED. This was the third failed attempt, so verification is now locked for this call. Do not try again. Do not share any account information. Offer to create a ticket so a specialist can verify them another way.';
  } else {
    result = `NOT VERIFIED. The details did not match. Do not say whether the ID or the answer was wrong. Attempts left: ${left}. Apologize briefly, then ask for the customer ID again and confirm it, and only after that ask for the security answer, as a separate question.`;
  }
}

return { json: { result } };
